glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
layout(std140) uniform CCLocal {
  highp mat4 cc_matWorld;
  highp mat4 cc_matWorldIT;
  highp vec4 cc_lightingMapUVParam;
  highp vec4 cc_localShadowBias;
  highp vec4 cc_reflectionProbeData1;
  highp vec4 cc_reflectionProbeData2;
  highp vec4 cc_reflectionProbeBlendData1;
  highp vec4 cc_reflectionProbeBlendData2;
};
in vec3 a_position;
in vec3 a_normal;
in vec2 a_texCoord;
in vec4 a_rimColor;
in float a_dissolve;
out vec2 v_uv;
out vec3 v_worldPos;
out vec3 v_worldNormal;
out vec4 v_rimColorInst;
out float v_dissolveInst;
vec4 vert() {
  vec4 worldPos4 = cc_matWorld * vec4(a_position, 1.0);
  v_worldPos    = worldPos4.xyz;
  v_worldNormal = normalize((cc_matWorldIT * vec4(a_normal, 0.0)).xyz);
  v_uv            = a_texCoord;
  v_rimColorInst  = a_rimColor;
  v_dissolveInst  = a_dissolve;
  return cc_matProj * cc_matView * worldPos4;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
vec4 CCFragOutput (vec4 color) {
  return color;
}
in vec2 v_uv;
in vec3 v_worldPos;
in vec3 v_worldNormal;
in vec4 v_rimColorInst;
in float v_dissolveInst;
uniform sampler2D mainTexture;
uniform sampler2D u_dissolveTex;
layout(std140) uniform UnitOutfit {
  vec4  u_primaryColor;
  vec4  u_secondaryColor;
  vec4  u_gradientTop;
  vec4  u_gradientBottom;
  vec4  u_gradientRange;
  vec4  u_emissionColor;
  vec4  u_rimColor;
  float u_emissionIntensity;
  float u_dissolve;
};
vec4 frag() {
  vec4 baseColor = texture(mainTexture, v_uv);
  vec3 color = baseColor.rgb * u_primaryColor.rgb;
  float yRange = u_gradientRange.y - u_gradientRange.x;
  float gradT  = (yRange > 0.001)
      ? clamp((v_worldPos.y - u_gradientRange.x) / yRange, 0.0, 1.0)
      : 0.5;
  vec3 gradColor = mix(u_gradientBottom.rgb, u_gradientTop.rgb, gradT);
  color = mix(color, color * gradColor, 0.4);
  vec3  viewDir = normalize(cc_cameraPos.xyz - v_worldPos);
  float NdotV   = max(dot(normalize(v_worldNormal), viewDir), 0.0);
  float rimFactor = pow(1.0 - NdotV, 2.5);
  vec4 activeRim = (v_rimColorInst.a > 0.01) ? v_rimColorInst : u_rimColor;
  color += activeRim.rgb * (activeRim.a * rimFactor);
  color += u_emissionColor.rgb * u_emissionIntensity;
  float dissolveVal = (v_dissolveInst >= 0.0) ? v_dissolveInst : u_dissolve;
  if (dissolveVal > 0.001) {
    float noise = texture(u_dissolveTex, v_uv * 1.5).r;
    if (noise < dissolveVal) {
      discard;
    }
    float edgeFactor = smoothstep(dissolveVal, dissolveVal + 0.05, noise);
    color = mix(vec3(1.0, 0.4, 0.0), color, edgeFactor);
  }
  return CCFragOutput(vec4(color, baseColor.a * u_primaryColor.a));
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

